from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def detect_image_text(payload, config=None):
    config = config or {}
    with ImageAnalysisClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.analyze(image_data=payload['image_bytes'], visual_features=[VisualFeatures.TEXT])
    text_regions = result.text.regions
    detected_text = ' '.join([line.text for region in text_regions for line in region.lines])
    return {'text': detected_text}

from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.ai.vision.imageanalysis.models import VisualFeatures
from azure.core.credentials import AzureKeyCredential


def score_image_safety(payload, config=None):
    config = config or {}
    with ImageAnalysisClient(config['endpoint'], AzureKeyCredential(config['api_key'])) as client:
        result = client.analyze(image_data=payload['image_bytes'], visual_features=[VisualFeatures.ADULT])
    adult_content = result.adult.is_adult_content
    racy_content = result.adult.is_racy_content
    safety_score = 0
    if not adult_content and not racy_content:
        safety_score = 100
    return {'safety_score': safety_score, 'is_safe': not adult_content and not racy_content}

from azure.ai.vision.imageanalysis import ImageAnalysisClient
from azure.core.credentials import AzureKeyCredential


class VisionClient:
    def __init__(self, endpoint, api_key):
        self.client = ImageAnalysisClient(endpoint, AzureKeyCredential(api_key))

    def detect_labels(self, image_bytes, max_labels=10):
        result = self.client.analyze(image_data=image_bytes, visual_features=[VisualFeatures.TAGS])
        tags = sorted(result.tags.list, key=lambda tag: tag.confidence, reverse=True)
        return [{'name': tag.name, 'confidence': tag.confidence} for tag in tags[:max_labels]]

    def describe_image(self, image_bytes):
        result = self.client.analyze(image_data=image_bytes, visual_features=[VisualFeatures.CAPTION])
        return result.caption.text

    def detect_text(self, image_bytes):
        result = self.client.analyze(image_data=image_bytes, visual_features=[VisualFeatures.TEXT])
        text_regions = result.text.regions
        detected_text = ' '.join([line.text for region in text_regions for line in region.lines])
        return detected_text

    def score_safety(self, image_bytes):
        result = self.client.analyze(image_data=image_bytes, visual_features=[VisualFeatures.ADULT])
        adult_content = result.adult.is_adult_content
        racy_content = result.adult.is_racy_content
        safety_score = 0
        if not adult_content and not racy_content:
            safety_score = 100
        return {'safety_score': safety_score, 'is_safe': not adult_content and not racy_content}

from azure.ai.vision.imageanalysis.models import VisualFeatures


def normalize_payload(payload):
    return {'image_bytes': payload['image_bytes'], 'config': payload.get('config', {})}


def parse_labels_response(response):
    return [{'name': tag.name, 'confidence': tag.confidence} for tag in response.tags.list]


def parse_description_response(response):
    return response.caption.text


def parse_text_response(response):
    text_regions = response.text.regions
    return ' '.join([line.text for region in text_regions for line in region.lines])


def parse_safety_response(response):
    adult_content = response.adult.is_adult_content
    racy_content = response.adult.is_racy_content
    safety_score = 0
    if not adult_content and not racy_content:
        safety_score = 100
    return {'safety_score': safety_score, 'is_safe': not adult_content and not racy_content}

from vision_client import VisionClient


def image_summary(payload, config=None):
    config = config or {}
    client = VisionClient(config['endpoint'], config['api_key'])
    labels = client.detect_labels(payload['image_bytes'], config.get('max_labels', 10))
    description = client.describe_image(payload['image_bytes'])
    text = client.detect_text(payload['image_bytes'])
    safety = client.score_safety(payload['image_bytes'])
    return {'labels': labels, 'description': description, 'text': text, 'safety': safety}

from azure.cognitiveservices.translation.text import TextTranslationClient
from msrest.authentication import CognitiveServicesCredentials


def alt_text_translate(payload, config=None):
    config = config or {}
    client = TextTranslationClient(credentials=CognitiveServicesCredentials(config['api_key']))
    translated_description = client.translate([payload['description']], to=config['target_language'])[0].text
    return {'translated_description': translated_description}

from azure.ai.textanalytics import TextAnalyticsClient
from azure.core.credentials import AzureKeyCredential


def visual_safety_text(payload, config=None):
    config = config or {}
    client = TextAnalyticsClient(config['endpoint'], AzureKeyCredential(config['api_key']))
    result = client.detect_language(payload['labels'])
    is_safe = all([not label['name'].lower() in config.get('unsafe_keywords', []) for label in result])
    return {'is_safe': is_safe}

from azure.storage.blob import BlobServiceClient


def image_asset_archive(payload, config=None):
    config = config or {}
    client = BlobServiceClient(account_url=config['storage_account_url'], credential=config['storage_account_key'])
    container_client = client.get_container_client(config['container_name'])
    blob_client = container_client.get_blob_client(config['blob_name'])
    with open(payload['image_path'], 'rb') as data:
        blob_client.upload_blob(data)
    return {'upload_status': 'success'}
